  const h=harness({retained:true,journalFactory:rig.factory,timers});await h.connect();
  const entered=deferred(),dispatch=deferred(),committed=deferred();
  h.beforeRoute=async c=>{if(c.path.endsWith('/question-intent')){entered.resolve();await dispatch.promise;}};
  h.setHook(c=>{if(c.path.endsWith('/question-intent'))committed.resolve();});
