  jobs.findLast(j=>!j.cleared&&j.ms===15000).fn();let s=await sending;
  assert.equal(s.error.code,'request_timeout');const receipt=rig.receipt(),reads=h.calls.length;
  assert.equal(receipt.requestId,null);s=await h.client.refresh();assert.equal(s.pendingMatch,null);assert.equal(s.uncertain,true);
  assert.deepEqual(rig.receipt(),receipt);assert(h.calls.slice(reads).every(c=>c.method==='GET'));
  dispatch.resolve();await committed.promise;h.beforeRoute=null;h.setHook(null);
