test('cold recovery requires exact digest, kind, draft and text before explicit cancellation of a lost draft prepare',async()=>{
  const rig=journalRig(),h=harness({journalFactory:rig.factory});await h.connect();await h.client.addFiles([selected()]);
  h.setHook(c=>{if(c.path.endsWith('/send-intent'))throw Error('Fictional lost committed preparation');});
  let s=await h.client.send('Exact captured text',rig.captureHooks());assert.equal(s.uncertain,true);
  const receipt=rig.receipt(),request=h.rows[0],before=h.calls.length;assert.equal(receipt.requestId,null);
  h.client.dispose();h.journal.dispose();h.makeClient();
  for(const mode of ['wrong-kind','wrong-draft','wrong-text','miss','row-absent','exact']){
    h.setHook((call,value)=>{
      if(call.path.includes('/requests/by-prepare?')){
        assert.equal(new URL('http://fictional.invalid'+call.path).searchParams.get('prepareDigest'),receipt.prepareDigest);
        if(mode==='wrong-kind')return {request:{...value.request,kind:'question'}};
        if(mode==='wrong-draft')return {request:{...value.request,draftId:id(999)}};
        if(mode==='miss')return {request:null};
      }
      if(!call.path.includes('/requests?'))return value;
      if(mode==='wrong-text')return {...value,items:[{...value.items[0],question:'Different text'}]};
      if(mode==='row-absent')return {...value,items:[]};
      return value;
    });
    s=mode==='wrong-kind'?await h.connect():await h.client.refresh();
    assert.equal(s.uncertain,true,mode);
    if(mode==='exact')assert.deepEqual(s.pendingMatch,{id:receipt.id,requestId:request.requestId});
    else {assert.equal(s.pendingMatch,null,mode);assert.equal(rig.receipt().requestId,null,mode);}
  }
  assert(h.calls.slice(before).every(c=>c.method==='GET'));assert.equal(h.calls.filter(c=>c.path.endsWith('/send')).length,0);
  h.setHook(c=>{if(c.path.includes('/requests/by-prepare?'))throw Error('Fictional recovery read failed');});
  s=await h.client.refresh();assert.equal(s.pendingMatch,null);assert.equal(s.complete,false);assert.equal(rig.receipt().requestId,request.requestId);
  h.setHook(null);s=await h.client.refresh();assert.deepEqual(s.pendingMatch,{id:receipt.id,requestId:request.requestId});
  s=await h.client.abandon(request.requestId);assert.equal(s.error,null);assert.equal(s.requests[0].abandoned,true);
  assert.equal(s.requests[0].officerDelivery.state,'not_sent');assert.equal(rig.receipt(),null);assert.equal(s.uncertain,false);assert.equal(s.savedDrafts[0].id,receipt.draftId);
  assert.equal(s.files.length,0);assert.equal(h.calls.filter(c=>c.path.endsWith('/send')).length,0);
});
