test('after either removal order the refused file is truthful: Remove leaves the draft, removing the sibling lets an explicit Add it admit it',async()=>{
  const limited=()=>{const h=harness();h.setHook((c,v)=>c.path.startsWith('/capabilities')?{...v,limits:{...v.limits,fileBytes:8,draftBytes:8}}:v);return h;};
  // Order 1: remove the refused file. The accepted draft is untouched and nothing is sent.
  let h=limited();await h.connect();let s=await h.client.addFiles([selected()]);const draftBefore=JSON.stringify(s.draft);let reads=0;const png={...selected('second.png','12345','image/png'),arrayBuffer:async()=>{reads++;return Uint8Array.from(Buffer.from('12345')).buffer;}};
  s=await h.client.addFiles([png]);let row=s.uploads.find(u=>u.state==='failed');let calls=h.calls.length;
  s=await h.client.removeUpload(row.id);assert.equal(s.uploads.some(u=>u.state==='failed'),false);assert.equal(JSON.stringify(s.draft),draftBefore);assert.equal(h.calls.length,calls);assert.equal(reads,0);
  s=await h.client.addRefused(row.id);assert.equal(h.calls.length,calls,'a removed row cannot be added');
  // Order 2: remove the accepted sibling. Only its DELETE runs; the refused row stays unread until Add it.
  h=limited();await h.connect();s=await h.client.addFiles([selected()]);reads=0;s=await h.client.addFiles([png]);row=s.uploads.find(u=>u.state==='failed');
  calls=h.calls.length;s=await h.client.addRefused(row.id);assert.equal(s.error.code,'draft_too_large','still too large together: Add it refuses again');assert.equal(s.uploads.filter(u=>u.state==='failed').length,1,'no duplicate row');assert.equal(s.uploads.find(u=>u.state==='failed').id,row.id);assert.equal(h.calls.length,calls);assert.equal(reads,0);
  const sibling=s.draft.files[0].id;s=await h.client.remove(sibling);
  assert.deepEqual(h.calls.slice(calls).map(c=>c.method),['DELETE']);assert.equal(s.draft.files.length,0);assert.equal(reads,0,'removing a sibling reads nothing');
  assert.equal(s.uploads.find(u=>u.id===row.id).state,'failed');assert.equal(s.uploads.find(u=>u.id===row.id).fileId,null);
  const sendCalls=h.calls.length;const blocked=await h.client.send('Fictional question');assert.equal(blocked.error.code,'selection_not_ready','Send stays off until the refused row is added or removed');assert.equal(h.calls.slice(sendCalls).filter(c=>c.method!=='GET').length,0);
  calls=h.calls.length;s=await h.client.addRefused(row.id);
  assert.equal(s.error,null);assert.equal(reads,1,'Add it reads the kept File once');assert.equal(s.uploads.some(u=>u.id===row.id),false);assert.equal(s.uploads.some(u=>u.state==='failed'),false);
  assert.equal(s.draft.files.length,1);assert.equal(s.draft.files[0].name,'second.png');assert.ok(h.calls.slice(calls).some(c=>c.path.endsWith('/upload-intents')));
  assertPrivate(s);assert.equal(JSON.stringify(s).includes('arrayBuffer'),false);
});
