test('follow-up selects only the recent eight available answers across shuffled pages and timestamp ties',async()=>{
  for(const count of [0,1,8,10]){
    const h=harness({retained:true}),rows=Array.from({length:count},(_,i)=>h.req(i+10));
    for(const r of rows){r.createdAt=20;r.answeredAt=1000-Number.parseInt(r.requestId.slice(-2),16);h.answers.set(r.answerId,h.ans(r));}
    const withdrawn=h.req(40);withdrawn.createdAt=21;
    h.answers.set(withdrawn.answerId,{...h.ans(withdrawn),state:'source_unavailable',text:null,sourceValidation:'invalid',suppliedFileIds:[]});
    const shuffled=[withdrawn,...rows.slice().reverse()];h.setRows(shuffled);
    h.setHook((c,v)=>c.path.includes('/requests?')?c.path.includes('cursor=')?{items:h.rows.slice(3),nextCursor:null}:{items:h.rows.slice(0,3),nextCursor:'fictional-next'}:v);
    await h.connect();let s=await h.client.send('Read the recent answers');assert.equal(s.error,null);
    const p=h.calls.find(c=>c.path.endsWith('/question-intent'));assert.equal(p.body.priorAnswerPolicy,'recent_available_8');
    assert.deepEqual(p.body.priorAnswerIds,rows.slice(-8).map(r=>r.answerId));assert.equal(s.answers.length,count+2);
    const sent=s.answers.find(a=>a.requestId===s.lastSend.requestId),window={policy:'recent_available_8',includedCount:Math.min(count,8),omittedOlder:count>8};
    assert.deepEqual(sent.priorAnswerWindow,window);assert.equal(sent.answeredAt,500.125);
    const before=h.calls.length;h.client.invalidate();s=await h.connect();assert.ok(h.calls.slice(before).every(c=>c.method==='GET'));
    assert.deepEqual(s.answers.find(a=>a.id===sent.id).priorAnswerWindow,window);
  }
});
test('duplicate answer identities and invalid window or timestamp DTOs prevent a new question',async()=>{
  for(const mode of ['duplicate','window-missing','window-extra','window-short','window-policy','window-bool','withdrawn-window','draft-window','time-missing','time-negative','time-string','time-bound']){
    const h=harness({retained:true}),r=h.req(10),a=h.ans(r);h.setRows([r]);
    if(mode==='duplicate')h.rows.push({...h.req(11),answerId:r.answerId});
    if(mode.startsWith('window-')||mode.endsWith('-window'))a.priorAnswerWindow={policy:'recent_available_8',includedCount:8,omittedOlder:true};
    if(mode==='window-missing')delete a.priorAnswerWindow;
    if(mode==='window-extra')a.priorAnswerWindow.extra=true;
    if(mode==='window-short')a.priorAnswerWindow.includedCount=7;
    if(mode==='window-policy')a.priorAnswerWindow.policy='invented';
    if(mode==='window-bool')a.priorAnswerWindow.omittedOlder=1;
    if(mode==='withdrawn-window')Object.assign(a,{state:'source_unavailable',text:null,sourceValidation:'invalid',suppliedFileIds:[]});
    if(mode==='draft-window')r.draftId=id(4);
    if(mode==='time-missing')delete a.answeredAt;
    if(mode==='time-negative')a.answeredAt=-1;
    if(mode==='time-string')a.answeredAt='100';
    if(mode==='time-bound')a.answeredAt=Number.MAX_SAFE_INTEGER;
    h.answers.set(r.answerId,a);
    const s=await h.connect();assert.equal(s.error.code,'invalid_response',mode);assert.equal(s.complete,false);assert.equal(s.usableFileCount,null);
    if(mode==='duplicate')assert.equal(h.calls.some(c=>c.path.startsWith('/answers/')),false);
    const before=h.calls.length;await h.client.send('A malformed projection cannot supply context');assert.equal(h.calls.length,before);
  }
});
test('only an exact window conflict clears a rejected preparation, then refresh and explicit Send use fresh evidence',async()=>{
  for(const status of [409,503,'spoof']){
    const h=harness({retained:true});await h.connect();
    h.beforeRoute=c=>{if(c.path.endsWith('/question-intent')){const r=h.req(10);h.rows.push(r);h.answers.set(r.answerId,h.ans(r));if(status==='spoof')throw Object.assign(Error('Fictional transport error'),{officerDocumentClient:true,status:409,code:'document_prior_window_changed'});}};
    h.setHook(c=>{if(c.path.endsWith('/question-intent')){h.rows.pop();return {error:{code:'document_prior_window_changed'}};}});
    h.responseHook=(c,v)=>c.path.endsWith('/question-intent')?{ok:false,status,json:async()=>v}:null;
    let s=await h.client.send('Read the exact current context');assert.equal(s.error.code,'document_prior_window_changed');assert.equal(s.uncertain,status!==409);
    if(status===409){assert.equal(s.complete,false);assert.equal(s.usableFileCount,null);assert.deepEqual(s.answers,[]);}
    assert.equal(h.calls.filter(c=>c.path.endsWith('/ask')).length,0);
    h.beforeRoute=null;h.setHook(null);h.responseHook=null;
    const before=h.calls.length;await h.client.send('Requires an explicit read');assert.equal(h.calls.length,before);
    s=await h.client.refresh();assert.ok(h.calls.slice(before).every(c=>c.method==='GET'));
    s=await h.client.send('Explicitly send again after observing new context');
    assert.equal(h.calls.filter(c=>c.path.endsWith('/ask')).length,status===409?1:0);
  }
});
test('only a verified pre-insert window refusal with a covered local outcome settles an unprepared receipt',async()=>{
  for(const mode of ['covered','uncovered','throw','wrong-status','spoof']){
    const rig=journalRig(),h=harness({retained:true,journalFactory:rig.factory});await h.connect();
    if(mode==='spoof')h.beforeRoute=c=>{if(c.path.endsWith('/question-intent'))throw Object.assign(Error('Fictional transport error'),{officerDocumentClient:true,status:409,code:'document_prior_window_changed'});};
    h.setHook(c=>{if(c.path.endsWith('/question-intent')){h.rows.pop();return {error:{code:'document_prior_window_changed'}};}});
    h.responseHook=(c,v)=>c.path.endsWith('/question-intent')?{ok:false,status:mode==='wrong-status'?503:409,json:async()=>v}:null;
    let captured,notice;const hooks=rig.captureHooks(receipt=>{captured=receipt;});
    hooks.onNotAsked=proof=>{notice=proof;assert.equal(rig.receipt().id,captured.id);if(mode==='throw')throw Error('Fictional presentation fault');return mode==='covered';};
    let s=await h.client.send('This exact file question is not asked.',hooks);assert.equal(s.error.code,'document_prior_window_changed');
    if(mode==='wrong-status'||mode==='spoof')assert.equal(notice,undefined);
    else assert.deepEqual(notice,{id:captured.id,reason:'prior_window_changed'});
    assert.equal(rig.receipt()?.id??null,mode==='covered'?null:captured.id);assert.equal(s.uncertain,mode!=='covered');
    assert.equal(h.calls.filter(c=>c.path.endsWith('/ask')).length,0);
    const before=h.calls.length;s=await h.client.refresh();assert(h.calls.slice(before).every(c=>c.method==='GET'));
    assert.equal(s.uncertain,mode!=='covered');
  }
});
