test('owner changes across each mutation response prevent dependent mutations',async()=>{for(const phase of ['create','draft','reserve','put','edit','prepare','execute']){const h=harness();await h.connect();if(['edit','prepare','execute'].includes(phase))await h.client.addFiles([selected()]);const match=c=>phase==='create'?c.path==='/conversations/current'&&c.method==='POST':phase==='draft'?c.path==='/drafts'&&c.method==='POST':phase==='reserve'?c.path.endsWith('/upload-intents'):phase==='put'?c.method==='PUT':phase==='edit'?c.method==='PATCH':phase==='prepare'?c.path.endsWith('/send-intent'):c.path.endsWith('/send');let index;h.setHook(c=>{if(match(c)){index=h.calls.length;h.setOwner('different-owner');}});await (['edit','prepare','execute'].includes(phase)?h.client.send('question'):h.client.addFiles([selected()]));assert.equal(h.calls.length,index,phase+' must stop at identity boundary');assert.equal(h.client.snapshot().context,null);assertPrivate(h.client.snapshot());}});
test('context switch and dispose suppress late replies and keep synchronous routing guard',async()=>{const h=harness({retained:true});await h.connect();const pause=deferred();h.setHook(async c=>{if(c.path.startsWith('/files?'))await pause.promise;});const pending=h.client.refresh();await settle();h.client.invalidate();assert.equal(h.client.snapshot().routing,'blocked');pause.resolve();await pending;assert.deepEqual(h.client.snapshot().answers,[]);assert.equal(h.client.snapshot().context,null);h.setHook(null);await h.connect();h.client.dispose();const count=h.calls.length;await h.client.refresh();await h.client.send('question');assert.equal(h.calls.length,count);assert.equal(h.client.snapshot().routing,'blocked');});
test('changed callback invalidation cannot launch a dependent request',async()=>{const h=harness();await h.connect();let done=false;h.changedHook=s=>{if(!done&&s.draft){done=true;h.client.invalidate();}};await h.client.addFiles([selected()]);assert.equal(h.calls.filter(c=>c.path.endsWith('/upload-intents')).length,0);assert.equal(h.client.snapshot().context,null);});
test('GET-only reload restoration retains no second answer/storage mirror or file bytes',async()=>{const h=harness({retained:true}),r=h.req(10);h.setRows([r]);h.answers.set(r.answerId,h.ans(r));const s=await h.connect();assertPrivate(s);assert.ok(!JSON.stringify(s).includes('ArrayBuffer'));assert.equal(h.calls.some(c=>c.method!=='GET'),false);h.client.invalidate();assert.equal(h.client.snapshot().answers.length,0);assert.equal(h.client.snapshot().files.length,0);assert.equal(h.client.snapshot().lastSend,null);});

test('explicit removal of a failed local selection and acknowledged server selection preserves siblings',async()=>{const h=harness();await h.connect();let s=await h.client.addFiles([{...selected(),arrayBuffer:async()=>new ArrayBuffer(5)}]);const local=s.uploads[0].id,count=h.calls.length;s=await h.client.removeUpload(local);assert.equal(s.uploads.length,0);assert.equal(h.calls.length,count);s=await h.client.addFiles([selected(),selected('second.pdf')]);const first=s.uploads[0],second=s.uploads[1];s=await h.client.removeUpload(first.id);assert.equal(s.uploads.length,1);assert.equal(s.uploads[0].id,second.id);assert.equal(s.draft.files.length,1);assert.equal(s.draft.files[0].id,second.fileId);assert.equal(h.calls.at(-1).method,'DELETE');});
test('bounded HTTP metadata timeout aborts once and cleans deadline, no retry',async()=>{const jobs=[];let cleared=0,aborted=0;const timers={setTimeout:(fn,ms)=>{jobs.push({fn,ms});return jobs.length;},clearTimeout:()=>cleared++};const h=harness({timers}),entered=deferred();h.setHook(async c=>{if(c.path.startsWith('/capabilities')){entered.resolve();await new Promise(()=>{});}});const pending=h.connect();await entered.promise;assert.equal(jobs[0].ms,15000);jobs[0].fn();const s=await pending;assert.equal(s.error.code,'request_timeout');assert.equal(s.busy,false);assert.equal(s.routing,'blocked');assert.equal(h.calls.length,1);assert.equal(cleared,1);});
test('bounded execution timeout retains known attempt and read recovery has no retry',async()=>{const jobs=[];const timers={setTimeout:(fn,ms)=>{const j={fn,ms,cleared:false};jobs.push(j);return j;},clearTimeout:j=>{j.cleared=true;}};const h=harness({timers});await h.connect();await h.client.addFiles([selected()]);h.setHook(async c=>{if(c.path.endsWith('/send'))await new Promise(()=>{});});const pending=h.client.send('question');await settle();const execute=jobs.find(j=>j.ms===130000&&!j.cleared);assert.ok(execute,'execute deadline covers server bound');execute.fn();let s=await pending;assert.equal(s.uncertain,true);assert.ok(s.lastSend.requestId);assert.equal(s.lastSend.retained,true);h.setHook(null);const count=h.calls.length;s=await h.client.refresh();assert.equal(s.uncertain,false);assert.ok(h.calls.slice(count).every(c=>c.method==='GET'));assert.ok(jobs.every(j=>j.cleared));});
test('bounded streaming response refuses overflow and cancels its reader',async()=>{const h=harness();let cancelled=0;h.responseHook=()=>({ok:true,body:{getReader:()=>({read:async()=>({done:false,value:new Uint8Array(262145)}),cancel:async()=>cancelled++,releaseLock(){}})}});const s=await h.connect();assert.equal(s.error.code,'invalid_response');assert.equal(s.complete,false);assert.equal(h.calls.length,1);assert.equal(cancelled,1);});
test('response authority fields cannot hide inside public delivery records or file errors',async()=>{const h=harness({retained:true}),r=h.req(10,'failed');r.officerDelivery.requestCapability='fictional-request-secret';r.officerDelivery.writerNonce='fictional-writer-secret';h.setRows([r]);const f=h.file();f.error={message:'fictional-owner-secret'};f.officerDelivery.sourceCapability='fictional-source-secret';h.setFiles([f]);const s=await h.connect();assert.equal(s.error,null);assert.equal(s.files[0].error,'file_unavailable');assertPrivate(s);});

test('proven no-call reasons are surfaced exactly and other values refuse',async()=>{for(const reason of ['no_question','budget_exhausted','context_too_large','reading_unavailable','invented_reason']){const h=harness({retained:true}),r=h.req(10,'retained_local');r.notAskedReason=reason;h.setRows([r]);const s=await h.connect();if(reason==='invented_reason')assert.equal(s.error.code,'invalid_response');else{assert.equal(s.error,null);assert.equal(s.requests[0].notAskedReason,reason);}}});
test('changing to an empty scope permits ordinary routing after exact read proof',async()=>{const h=harness({retained:true});await h.connect();h.setConversation(null);const s=await h.client.connect({scopeId:'station:fictional',modelId:model});assert.equal(s.routing,'ordinary');assert.equal(s.complete,true);assert.equal(s.context.scopeId,'station:fictional');assert.equal(h.calls.some(c=>c.method!=='GET'),false);});
test('raw numeric DOM errors never expose transport exception text',async()=>{const h=harness();h.setHook(()=>{const e=Error('RAW PRIVATE EXCEPTION');e.code=20;throw e;});const s=await h.connect();assert.equal(s.error.code,'transport_unavailable');assert.ok(!JSON.stringify(s).includes('RAW PRIVATE'));});

test('follow-up rechecks eligibility when GET revalidation discovers another window unresolved request',async()=>{for(const state of ['unknown','preparing']){const h=harness({retained:true});await h.connect();const other=h.req(10,state,'Another window question');h.setRows([other]);const count=h.calls.length;const s=await h.client.send('Do not submit this followup');assert.equal(s.error.code,'mutation_blocked');assert.equal(s.uncertain,true);assert.equal(s.lastSend.retained,false);assert.equal(s.requests[0].requestId,other.requestId);assert.ok(h.calls.slice(count).every(c=>c.method==='GET'));assert.equal(h.calls.filter(c=>c.method==='POST').length,0);}});
test('lost follow-up execute left prepared/not_sent cannot prove composer text retained',async()=>{const h=harness({retained:true});await h.connect();h.setHook(c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){const row=h.rows.find(r=>r.requestId===c.path.split('/')[2]);row.state='prepared';row.canAbandon=true;row.officerDelivery={state:'not_sent',requestId:null};row.answerId=null;throw Error('execute request never reached consumption');}});let s=await h.client.send('Preserve this exact composer text');assert.equal(s.uncertain,true);assert.equal(s.lastSend.retained,false);const requestId=s.lastSend.requestId;assert.ok(requestId);h.setHook(null);const count=h.calls.length;s=await h.client.refresh();assert.equal(s.requests[0].requestId,requestId);assert.equal(s.requests[0].question,'Preserve this exact composer text');assert.equal(s.requests[0].state,'prepared');assert.equal(s.requests[0].officerDelivery.state,'not_sent');assert.equal(s.lastSend.retained,false);assert.equal(s.uncertain,true);assert.ok(h.calls.slice(count).every(c=>c.method==='GET'));assert.equal(h.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,1);});

test('same-client reconnect preserves in-flight attempt while prepared history blocks second execution',async()=>{const h=harness({retained:true});await h.connect();const gate=deferred(),entered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=h.client.send('First issued question');await entered.promise;assert.equal(h.rows[0].state,'prepared');assert.equal(h.rows[0].officerDelivery.state,'not_sent');let s=await h.connect();assert.equal(s.uncertain,true);const count=h.calls.length;await h.client.send('Blocked second question');assert.equal(h.calls.length,count);assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,1);assert.equal(h.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,1);h.beforeRoute=null;gate.resolve();await first;s=await h.client.refresh();assert.equal(s.uncertain,false);assert.equal(s.requests[0].state,'answered');assert.ok(h.calls.slice(count).every(c=>c.method==='GET'));await h.client.send('New explicit question after reconciliation');assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,2);assert.equal(h.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,2);});
test('cold replacement client treats every restored prepared attempt as unresolved until terminal GET reconciliation',async()=>{const issuing=harness({retained:true});await issuing.connect();const gate=deferred(),entered=deferred();issuing.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=issuing.client.send('Question issued by another client');await entered.promise;assert.equal(issuing.rows[0].state,'prepared');const cold=harness({retained:true,counter:500});cold.setRows(issuing.rows);let s=await cold.connect();assert.equal(s.uncertain,true);assert.equal(s.requests[0].state,'prepared');await cold.client.send('Blocked duplicate question');assert.equal(cold.calls.filter(c=>c.method==='POST').length,0);issuing.beforeRoute=null;gate.resolve();await first;for(const [key,value] of issuing.answers)cold.answers.set(key,value);const count=cold.calls.length;s=await cold.client.refresh();assert.equal(s.uncertain,false);assert.equal(s.requests[0].state,'answered');assert.ok(cold.calls.slice(count).every(c=>c.method==='GET'));await cold.client.send('Later explicit question');assert.equal(cold.calls.filter(c=>c.path.endsWith('/question-intent')).length,1);assert.equal(cold.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,1);});
test('same-identity reconnect cannot discard an issued identity even when restored history omits it',async()=>{const h=harness({retained:true});await h.connect();const gate=deferred(),entered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=h.client.send('Exact pending question');await entered.promise;h.setHook((c,v)=>c.path.startsWith('/conversations/')&&c.path.includes('/requests')?{items:[],nextCursor:null}:v);let s=await h.connect();assert.deepEqual(s.requests,[]);assert.equal(s.uncertain,true);const count=h.calls.length;await h.client.send('Must remain blocked');assert.equal(h.calls.length,count);h.setHook(null);h.beforeRoute=null;gate.resolve();await first;s=await h.client.refresh();assert.equal(s.uncertain,false);assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,1);});

test('lost question preparation can be explicitly abandoned before a later new explicit Send',async()=>{const h=harness({retained:true});await h.connect();h.setHook(c=>{if(c.path.endsWith('/question-intent'))throw Error('lost preparation acknowledgement');});let s=await h.client.send('Prepared question with lost acknowledgement');assert.equal(s.uncertain,true);assert.equal(s.lastSend.retained,false);assert.equal(h.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,0);h.setHook(null);s=await h.client.refresh();const exact=s.requests[0];assert.equal(exact.canAbandon,true);assert.equal(exact.abandoned,false);assert.equal(exact.draftId,null);s=await h.client.abandon(exact.requestId);assert.equal(s.uncertain,false);assert.equal(s.requests[0].abandoned,true);assert.equal(s.requests[0].state,'failed');assert.equal(s.requests[0].officerDelivery.state,'not_sent');assert.equal(s.lastSend.retained,false);assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,1);assert.equal(h.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,0);await h.client.send('A later explicit question');assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,2);assert.equal(h.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,1);assertPrivate(h.client.snapshot());});
test('lost draft preparation abandonment releases only its exact draft for explicit Resume with files and text intact',async()=>{const h=harness();await h.connect();await h.client.addFiles([selected()]);h.setHook(c=>{if(c.path.endsWith('/send-intent'))throw Error('lost draft preparation acknowledgement');});let s=await h.client.send('Exact preserved draft text');assert.equal(s.uncertain,true);assert.equal(s.lastSend.retained,true);const draftId=s.draft.id,fileId=s.draft.files[0].id;h.setHook(null);s=await h.client.refresh();const exact=s.requests[0];assert.equal(exact.draftId,draftId);assert.equal(exact.canAbandon,true);s=await h.client.abandon(exact.requestId);assert.equal(s.uncertain,false);assert.equal(s.draft,null);assert.equal(s.savedDrafts[0].id,draftId);assert.equal(h.calls.some(c=>c.path.endsWith('/resume')),false);s=await h.client.resume(draftId);assert.equal(s.error,null);assert.equal(s.draft.text,'Exact preserved draft text');assert.equal(s.draft.files[0].id,fileId);assert.equal(s.draft.files[0].state,'ready');s=await h.client.send('Exact preserved draft text');assert.equal(s.error,null);assert.equal(s.requests.filter(r=>r.abandoned).length,1);assert.equal(s.requests.filter(r=>r.state==='answered').length,1);assert.equal(h.calls.filter(c=>c.path.endsWith('/send-intent')).length,2);assert.equal(h.calls.filter(c=>c.path.endsWith('/send')).length,1);});
test('lost abandonment acknowledgement stays uncertain until GET proves the exact terminal abandoned request',async()=>{const h=harness({retained:true}),r=h.req(10,'prepared');h.setRows([r]);await h.connect();h.setHook(c=>{if(c.path.endsWith('/abandon'))throw Error('lost abandonment response');});let s=await h.client.abandon(r.requestId);assert.equal(s.uncertain,true);const count=h.calls.length;await h.client.send('Must not run');assert.equal(h.calls.length,count);h.setHook(null);s=await h.client.refresh();assert.equal(s.requests[0].abandoned,true);assert.equal(s.requests[0].canAbandon,false);assert.equal(s.uncertain,false);assert.ok(h.calls.slice(count).every(c=>c.method==='GET'));assert.equal(h.calls.filter(c=>c.path.endsWith('/abandon')).length,1);});
test('abandonment is explicit, exact-current-request only, and works despite qualification refusal',async()=>{const h=harness({retained:true,unqualified:true}),r=h.req(10,'prepared');h.setRows([r]);let s=await h.connect();assert.equal(s.available,false);assert.equal(s.uncertain,true);const count=h.calls.length;await h.client.abandon(id(99));assert.equal(h.calls.length,count);s=await h.client.abandon(r.requestId);assert.equal(s.error,null);assert.equal(s.available,false);assert.equal(s.requests[0].abandoned,true);assert.equal(s.uncertain,false);assert.equal(h.calls.filter(c=>c.path.endsWith('/abandon')).length,1);});
test('abandon loses to prior consumption without claiming cancellation and GET discovers the actual outcome',async()=>{const h=harness({retained:true}),r=h.req(10,'prepared');h.setRows([r]);await h.connect();r.state='unknown';r.canAbandon=false;r.officerDelivery={state:'unknown',requestId:r.requestId};let s=await h.client.abandon(r.requestId);assert.equal(s.error.code,'request_already_started');assert.equal(s.uncertain,true);assert.equal(r.abandoned,false);s=await h.client.refresh();assert.equal(s.requests[0].state,'unknown');assert.equal(s.requests[0].abandoned,false);assert.equal(s.uncertain,true);});
test('one abandoned draft intent cannot unblock another unresolved intent for the same draft',async()=>{const h=harness();await h.connect();await h.client.addFiles([selected()]);h.setHook(c=>{if(c.path.endsWith('/send-intent'))throw Error('lost');});await h.client.send('Exact draft');h.setHook(null);const another=h.req(500,'prepared','Another intent');another.draftId=id(4);h.rows.push(another);let s=await h.client.refresh();s=await h.client.abandon(s.requests[0].requestId);assert.equal(s.uncertain,true);const count=h.calls.length;await h.client.resume(id(4));assert.equal(h.calls.length,count);s=await h.client.abandon(another.requestId);assert.equal(s.uncertain,false);s=await h.client.resume(id(4));assert.equal(s.error,null);assert.equal(s.draft.text,'Exact draft');});
test('abandonment metadata rejects inconsistent flags, invalid draft identities and changed immutable draft relationships',async()=>{for(const mutation of [r=>r.canAbandon=false,r=>r.abandoned=true,r=>r.draftId='not-an-id']){const h=harness({retained:true}),r=h.req(10,'prepared');mutation(r);h.setRows([r]);const s=await h.connect();assert.equal(s.error.code,'invalid_response');}const h=harness({retained:true}),r=h.req(10,'prepared');h.setRows([r]);await h.connect();h.setHook((c,v)=>c.path.startsWith('/conversations/')&&c.path.includes('/requests')?{items:[{...r,draftId:id(4)}],nextCursor:null}:v);const s=await h.client.refresh();assert.equal(s.error.code,'invalid_response');});

test('invalidate synchronously clears prose and authority while same-identity reconnect preserves held execution even with empty history',async()=>{for(const hidden of [false,true]){const h=harness({retained:true}),prior=h.req(10);h.setRows([prior]);h.answers.set(prior.answerId,h.ans(prior));let s=await h.connect();const staleHandle=s.files[0].previewHandle;const gate=deferred(),entered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=h.client.send('Issued before visibility pause');await entered.promise;assert.ok(h.client.snapshot().answers.some(a=>a.text));h.client.invalidate();s=h.client.snapshot();assert.equal(s.context,null);assert.equal(s.routing,'blocked');assert.deepEqual(s.answers,[]);assert.deepEqual(s.files,[]);assert.deepEqual(s.requests,[]);assert.equal(s.draft,null);assert.equal(s.lastSend,null);assert.equal(s.preview,null);assertPrivate(s);const pausedCount=h.calls.length;await h.client.refresh();await h.client.preview(staleHandle);assert.equal(h.calls.length,pausedCount,'paused methods must neither transport nor discard the issued carry');if(hidden)h.setHook((c,v)=>c.path.startsWith('/conversations/')&&c.path.includes('/requests')?{items:[],nextCursor:null}:v);s=await h.connect();assert.equal(s.uncertain,true);if(hidden)assert.deepEqual(s.requests,[]);const count=h.calls.length;await h.client.send('Blocked duplicate after visibility resume');assert.equal(h.calls.length,count);assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,1);assert.equal(h.calls.filter(c=>c.path.startsWith('/requests/')&&c.path.endsWith('/ask')).length,1);h.setHook(null);h.beforeRoute=null;gate.resolve();await first;s=await h.client.refresh();assert.equal(s.uncertain,false);assert.ok(h.calls.slice(count).every(c=>c.method==='GET'));await h.client.send('Explicit next question after status proof');assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,2);}});
test('suspended issued holds never restore to another owner, scope or model',async()=>{for(const change of ['owner','scope','model']){const h=harness({retained:true});await h.connect();const gate=deferred(),entered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=h.client.send('Old identity pending question');await entered.promise;h.client.invalidate();h.client.invalidate();if(change==='owner')h.setOwner('different-owner');const scope=change==='scope'?'station:fictional':'room',selectedModel=change==='model'?'unsupported-model':model;h.setHook((c,v)=>{if(c.path.startsWith('/capabilities')&&change==='model')return {available:false,destinationId:'officer',scopeId:scope,modelId:selectedModel};if(c.path.startsWith('/conversations/current')&&change==='scope')return {conversation:null};if(c.path.startsWith('/conversations/')&&c.path.includes('/requests'))return {items:[],nextCursor:null};return v;});const s=await h.client.connect({scopeId:scope,modelId:selectedModel});assert.equal(s.uncertain,false,change+' identity must not inherit an old issued hold');assert.equal(s.complete,true);assert.equal(s.context.scopeId,scope);assert.equal(s.context.modelId,selectedModel);assertPrivate(s);h.beforeRoute=null;gate.resolve();await first;assert.equal(h.client.snapshot().context.scopeId,scope);assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,1);}});
test('dispose permanently drops suspended issued holds and performs no reconnection',async()=>{const h=harness({retained:true});await h.connect();const gate=deferred(),entered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=h.client.send('Pending final disposal');await entered.promise;h.client.invalidate();h.client.dispose();const count=h.calls.length;await h.connect();await h.client.refresh();assert.equal(h.calls.length,count);assert.equal(h.client.snapshot().context,null);assert.equal(h.client.snapshot().uncertain,false);gate.resolve();await first;assert.deepEqual(h.client.snapshot().answers,[]);assert.equal(h.client.snapshot().context,null);});

test('verified identity and issued holds survive invalidate during a direct same-context reconnect owner digest',async()=>{const h=harness({retained:true});await h.connect();const executeGate=deferred(),executeEntered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){executeEntered.resolve();await executeGate.promise;}};const first=h.client.send('A issued before digest transition');await executeEntered.promise;const digestGate=deferred(),digestEntered=deferred();let digestHeld=false;h.digestHook=async()=>{if(!digestHeld){digestHeld=true;digestEntered.resolve();await digestGate.promise;}};h.setHook((c,v)=>c.path.startsWith('/conversations/')&&c.path.includes('/requests')?{items:[],nextCursor:null}:v);const reconnecting=h.connect();await digestEntered.promise;h.client.invalidate();assert.equal(h.client.snapshot().context,null);assert.deepEqual(h.client.snapshot().answers,[]);let s=await h.connect();assert.deepEqual(s.requests,[]);assert.equal(s.uncertain,true);const count=h.calls.length;await h.client.send('Must remain blocked while A may consume');assert.equal(h.calls.length,count);digestGate.resolve();await reconnecting;assert.equal(h.client.snapshot().uncertain,true);h.digestHook=null;h.setHook(null);h.beforeRoute=null;executeGate.resolve();await first;s=await h.client.refresh();assert.equal(s.uncertain,false);assert.ok(s.requests.some(r=>r.question==='A issued before digest transition'&&r.state==='answered'));assert.ok(h.calls.slice(count).every(c=>c.method==='GET'));await h.client.send('Later explicit question after A terminal');assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,2);});
test('multiple explicit abandonments cannot consume an unrelated issued hold omitted from history',async()=>{const h=harness({retained:true});await h.connect();const gate=deferred(),entered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=h.client.send('Held A must retain its own uncertainty');await entered.promise;const a=h.rows[0],b=h.req(600,'prepared','Prepared B'),c=h.req(700,'prepared','Prepared C');h.rows.push(b,c);h.setHook((call,value)=>call.path.startsWith('/conversations/')&&call.path.includes('/requests')?{items:h.rows.filter(r=>r.requestId!==a.requestId),nextCursor:null}:call.path==='/requests/'+b.requestId+'/abandon'?Promise.reject(Error('lost B abandon acknowledgement')):value);let s=await h.connect();assert.deepEqual(s.requests.map(r=>r.requestId),[b.requestId,c.requestId]);s=await h.client.abandon(b.requestId);assert.equal(s.uncertain,true);assert.equal(b.abandoned,true);s=await h.client.abandon(c.requestId);assert.equal(c.abandoned,true);assert.equal(s.requests.every(r=>r.abandoned),true);assert.equal(s.uncertain,true,'A requires its own terminal evidence despite terminal B/C');const count=h.calls.length;await h.client.send('No second execution may be issued');assert.equal(h.calls.length,count);h.client.invalidate();s=await h.connect();assert.equal(s.uncertain,true,'all flat holds survive another lifecycle pause');await h.client.send('Still blocked after lifecycle pause');assert.equal(h.calls.filter(call=>call.path.endsWith('/question-intent')).length,1);h.setHook(null);h.beforeRoute=null;gate.resolve();await first;s=await h.client.refresh();assert.equal(s.uncertain,false);assert.equal(s.requests.find(r=>r.requestId===a.requestId).state,'answered');assert.equal(h.calls.filter(call=>call.path.startsWith('/requests/')&&call.path.endsWith('/ask')).length,1);await h.client.send('New explicit question after exact A proof');assert.equal(h.calls.filter(call=>call.path.endsWith('/question-intent')).length,2);});

test('Auto requires exact effective-model proof and keeps the selected binding through upload, Send and follow-up',async()=>{const h=harness({selectedModel:'@automatic'});let s=await h.connect();assert.equal(s.available,true);assert.equal(s.context.modelId,'@automatic');assert.equal(h.calls.some(c=>c.method!=='GET'),false);s=await h.client.addFiles([selected()]);assert.equal(s.error,null);assert.equal(h.draft.destination.modelId,'auto');assert.equal(h.calls.find(c=>c.path==='/drafts'&&c.method==='POST').body.modelId,'auto');s=await h.client.send('Question on the selected Auto route');assert.equal(s.error,null);assert.equal(s.context.modelId,'@automatic');assert.equal(s.answers[0].model.id,model);assert.equal(h.rows[0].destination.modelId,'auto');s=await h.client.send('Explicit Auto follow-up');assert.equal(s.error,null);assert.equal(h.calls.find(c=>c.path.endsWith('/question-intent')).body.modelId,'auto');assert.equal(s.context.modelId,'@automatic');assert.ok(s.answers.every(a=>a.model.id===model));});
test('Auto refuses absent, mismatched or remapped effective-model advertisement',async()=>{for(const mode of ['absent','wrong-effective','remapped-selected']){const h=harness({selectedModel:'@automatic'});h.setHook((c,v)=>{if(!c.path.startsWith('/capabilities'))return v;const changed={...v};if(mode==='absent')delete changed.effectiveModelId;if(mode==='wrong-effective')changed.effectiveModelId='unsupported-model';if(mode==='remapped-selected')changed.modelId=model;return changed;});const s=await h.connect();assert.equal(s.available,false);assert.equal(s.routing,'blocked');assert.equal(h.calls.some(c=>c.method!=='GET'),false);assert.equal(s.context.modelId,'@automatic');}});
test('an explicit unsupported model refuses even when a fake advertises qualified effective Haiku',async()=>{const h=harness({selectedModel:'unsupported-explicit-model'});const s=await h.connect();assert.equal(s.available,false);assert.equal(s.routing,'blocked');assert.equal(s.context.modelId,'unsupported-explicit-model');assert.equal(h.calls.some(c=>c.method!=='GET'),false);});
test('Auto and explicit Haiku fence saved drafts while historical responses retain their actual model',async()=>{const h=harness({selectedModel:'@automatic',retained:true});const historical=h.req(10);historical.destination.modelId=model;h.setRows([historical]);h.answers.set(historical.answerId,h.ans(historical));let s=await h.connect();assert.equal(s.available,true);assert.equal(s.context.modelId,'@automatic');assert.equal(s.answers[0].model.id,model);await h.client.addFiles([selected()]);const exactDraft=h.draft.id;assert.equal(h.draft.destination.modelId,'auto');s=await h.client.connect({scopeId:'room',modelId:model});assert.equal(s.available,true);assert.equal(s.context.modelId,model);assert.deepEqual(s.savedDrafts,[]);assert.equal(s.draft,null);const count=h.calls.length;await h.client.resume(exactDraft);assert.equal(h.calls.length,count,'another selected-model draft cannot be resumed');s=await h.connect();assert.equal(s.savedDrafts[0].id,exactDraft);s=await h.client.resume(exactDraft);assert.equal(s.error,null);assert.equal(s.context.modelId,'@automatic');assert.equal(s.draft.id,exactDraft);assert.equal(s.answers[0].model.id,model);assert.equal(h.draft.destination.modelId,'auto');});
test('reload under either supported selection accepts historical Auto and Haiku request bindings without remapping',async()=>{for(const selectedModel of ['@automatic',model]){const h=harness({selectedModel,retained:true}),oldAuto=h.req(10),oldHaiku=h.req(11);oldAuto.destination.modelId='auto';oldHaiku.destination.modelId=model;h.setRows([oldHaiku,oldAuto]);for(const r of [oldAuto,oldHaiku])h.answers.set(r.answerId,h.ans(r));const s=await h.connect();assert.equal(s.error,null);assert.equal(s.context.modelId,selectedModel);assert.equal(s.answers.length,2);assert.ok(s.answers.every(a=>a.model.id===model));assert.equal(h.calls.some(c=>c.method!=='GET'),false);assert.equal(h.rows.find(r=>r.requestId===oldAuto.requestId).destination.modelId,'auto');assert.equal(h.rows.find(r=>r.requestId===oldHaiku.requestId).destination.modelId,model);}});

test('only the real saved Auto sentinel maps narrowly to the attachment alias without widening scope/model grammar',async()=>{const h=harness({selectedModel:'@automatic'});let s=await h.connect();assert.equal(s.available,true);assert.equal(s.context.modelId,'@automatic');const capabilities=h.calls.find(c=>c.path.startsWith('/capabilities'));assert.equal(new URL('http://fictional.invalid'+capabilities.path).searchParams.get('modelId'),'auto');assert.ok(!capabilities.path.includes('%40automatic'));for(const selected of ['auto','@Automatic','@automatic-extra','@other']){const bad=harness({selectedModel:selected});s=await bad.connect();assert.equal(s.available,false);assert.equal(s.routing,'blocked');assert.equal(bad.calls.length,0,'unrecognized saved sentinel must never obtain an alias capability');}const badScope=harness();s=await badScope.client.connect({scopeId:'@automatic',modelId:'@automatic'});assert.equal(s.routing,'blocked');assert.equal(badScope.calls.length,0);});

test('every upload emission owns local selections before server mapping and never advertises ordinary routing',async()=>{for(const outcome of ['success','read-failed','create-lost']){const h=harness();await h.connect();const begin=h.changes.length;let file=selected();if(outcome==='read-failed')file={...file,arrayBuffer:async()=>{throw Error('fictional read failure');}};if(outcome==='create-lost')h.setHook(call=>{if(call.path==='/conversations/current'&&call.method==='POST')throw Error('lost create acknowledgement');});let s=await h.client.addFiles([file]);for(const emitted of h.changes.slice(begin)){if(emitted.uploads.length||emitted.draft||emitted.uncertain)assert.notEqual(emitted.routing,'ordinary',outcome+' local ownership cannot fall through ordinary routing');if(emitted.routing==='documents')assert.ok(emitted.conversation,'documents routing requires the exact mapped conversation');}if(outcome==='success'){assert.equal(s.routing,'documents');continue;}h.setHook(null);const refreshBegin=h.changes.length;s=await h.client.refresh();for(const emitted of h.changes.slice(refreshBegin))if(emitted.uploads.length||emitted.draft||emitted.uncertain)assert.notEqual(emitted.routing,'ordinary');if(outcome==='read-failed'){assert.equal(s.routing,'blocked');s=await h.client.removeUpload(s.uploads[0].id);assert.equal(s.routing,'ordinary');assert.deepEqual(s.uploads,[]);}else{assert.equal(s.routing,'documents');assert.ok(s.conversation);}}});

test('management-only construction needs no model qualification, document history or provider routing',async()=>{const h=harness({retained:true,documentsEnabled:false});let s=await h.client.connect({scopeId:'room',modelId:null});assert.equal(s.context.modelId,null);assert.equal(s.documentsEnabled,false);assert.equal(s.available,false);assert.equal(s.routing,'documents');assert.equal(s.management.available,true);assert.equal(s.management.complete,true);assert.equal(s.management.files[0].canDelete,true);assert.deepEqual(s.files,[]);assert.ok(h.calls.every(c=>c.method==='GET'&&(c.path.startsWith('/conversations/current')||c.path.includes('/management'))));const before=h.calls.length;await h.client.send('Reading stays unavailable');assert.equal(h.calls.length,before);s=await h.client.prepareDeletion(s.management.files[0].id);assert.equal(s.error,null);assert.equal(s.deletion.state,'confirm');assert.equal(s.deletion.confirmation.copyCount,1);assert.equal(h.cleanupCalls,0);assertPrivate(s);s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.error,null);assert.equal(s.deletion.state,'deleted');assert.equal(s.deletion.releasedBytes,4);assert.equal(s.management.files[0].available,false);assert.equal(s.management.files[0].canDelete,false);assert.equal(h.cleanupCalls,1);assertPrivate(s);});
test('base-service unavailable document history falls back to management while other history errors remain explicit',async()=>{for(const code of ['unavailable','document_context_changed']){const h=harness({retained:true,unqualified:true});h.setHook((c,v)=>c.path.startsWith('/conversations/')&&c.path.includes('/requests')?{error:{code,message:'No reading service'}}:v);const s=await h.connect();assert.equal(s.management.available,true);assert.equal(s.management.complete,true);assert.equal(s.available,false);assert.equal(s.routing,'documents');if(code==='unavailable'){assert.equal(s.error,null);assert.equal(s.complete,true);}else{assert.equal(s.error.code,code);assert.equal(s.complete,false);}}});
test('D1 management navigates more than fifty pages and deletes the exact displayed source without reading unseen document history',async()=>{const h=harness({retained:true,documentsEnabled:false,managementCount:2551});let s=await h.client.connect({scopeId:'room',modelId:null});assert.equal(s.management.files.length,50);for(let page=1;page<52;page++){assert.ok(s.management.nextHandle);s=await h.client.managementPage(s.management.nextHandle);assert.equal(s.error,null);assert.equal(s.management.page,page+1);}assert.equal(s.management.files.length,1);const exact=s.management.files[0].id;assert.equal(exact,id(2552));s=await h.client.prepareDeletion(exact);assert.equal(s.deletion.fileId,exact);s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.error,null);assert.equal(s.deletion.fileId,exact);assert.equal(s.deletion.state,'deleted');assert.equal(h.cleanupCalls,1);assert.ok(h.calls.every(c=>!c.path.includes('/requests')&&!c.path.startsWith('/files?')&&!c.path.startsWith('/answers/')));assert.ok(!JSON.stringify(s).includes('signed-management-'));s=await h.client.managementPage(s.management.firstHandle);assert.equal(s.management.page,1);assert.equal(s.management.files[0].available,true);});
test('a management source remains deletable when full governed history exceeds its existing bounds',async()=>{const h=harness({retained:true,managementCount:51});let s=await h.connect();assert.equal(s.complete,false);assert.equal(s.management.complete,true);assert.equal(s.management.files.length,50);s=await h.client.prepareDeletion(s.management.files[0].id);assert.equal(s.deletion.state,'confirm');s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.deletion.state,'deleted');assert.equal(h.cleanupCalls,1);assert.equal(s.management.complete,true);});
test('D2 stale confirmation A cannot upgrade through the stable operation ID after preview B replaces it',async()=>{const h=harness({retained:true,documentsEnabled:false});let s=await h.connect();const file=s.management.files[0].id;s=await h.client.prepareDeletion(file);const a=s.deletion;s=await h.client.closeDeletion();s=await h.client.prepareDeletion(file);const b=s.deletion;assert.equal(a.id,b.id);assert.equal(b.revision,a.revision+1);assert.notEqual(a.confirmationHandle,b.confirmationHandle);const before=h.calls.length;await h.client.confirmDeletion(a.confirmationHandle);assert.equal(h.calls.length,before);assert.equal(h.cleanupCalls,0);s=await h.client.confirmDeletion(b.confirmationHandle);assert.equal(s.deletion.state,'deleted');assert.equal(h.cleanupCalls,1);const opens=h.calls.length;s=await h.client.openDeletion(a.operationHandle);assert.equal(s.error.code,'deletion_unavailable');assert.equal(h.calls.length,opens);assert.equal(h.cleanupCalls,1);});
test('lost preparation is reconciled by GET and explicit exact reopen without another prepare',async()=>{const h=harness({retained:true,documentsEnabled:false});let s=await h.connect();h.setHook(c=>{if(c.path.endsWith('/deletion-intent'))throw Error('lost preparation');});s=await h.client.prepareDeletion(s.management.files[0].id);assert.equal(s.uncertain,true);assert.equal(s.deletion,null);const prepared=h.calls.length;await h.client.prepareDeletion(s.management.files[0].id);assert.equal(h.calls.length,prepared);h.setHook(null);s=await h.client.refresh();assert.equal(s.uncertain,false);assert.equal(s.deletions[0].state,'confirm');const reads=h.calls.length;s=await h.client.openDeletion(s.deletions[0].operationHandle);assert.equal(s.deletion.state,'confirm');assert.ok(h.calls.slice(reads).every(c=>c.method==='GET'));assert.equal(h.calls.filter(c=>c.path.endsWith('/deletion-intent')).length,1);});
test('confirmation withdraws governed prose before dispatch and lost acknowledgement remains GET-only recovery after close',async()=>{const h=harness({retained:true}),r=h.req(10);h.setRows([r]);h.answers.set(r.answerId,h.ans(r));let s=await h.connect();assert.ok(s.answers[0].text);s=await h.client.prepareDeletion(s.management.files[0].id);h.beforeRoute=c=>{if(c.path.endsWith('/confirm')){assert.deepEqual(h.client.snapshot().answers,[]);assert.equal(h.client.snapshot().preview,null);}};h.setHook(c=>{if(c.path.endsWith('/confirm'))throw Error('lost confirmation');});s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.uncertain,true);assert.deepEqual(s.answers,[]);const before=h.calls.length;await h.client.closeDeletion();assert.equal(h.client.snapshot().deletion,null);assert.equal(h.cleanupCalls,1);h.setHook(null);h.beforeRoute=null;s=await h.client.refresh();assert.equal(s.uncertain,false);assert.equal(s.deletions[0].state,'deleted');assert.equal(s.answers[0].text,null);assert.ok(h.calls.slice(before).every(c=>c.method==='GET'));assert.equal(h.calls.filter(c=>c.path.endsWith('/confirm')).length,1);});
test('pre-dispatch lost confirm requires an exact GET reopen and fresh UI handle, reusing its command key explicitly',async()=>{const h=harness({retained:true,documentsEnabled:false});let s=await h.connect();s=await h.client.prepareDeletion(s.management.files[0].id);const old=s.deletion.confirmationHandle;let failOnce=true;h.beforeRoute=c=>{if(c.path.endsWith('/confirm')&&failOnce){failOnce=false;throw Error('not yet delivered');}};s=await h.client.confirmDeletion(old);assert.equal(s.uncertain,true);const first=h.calls.find(c=>c.path.endsWith('/confirm'));const count=h.calls.length;await h.client.confirmDeletion(old);assert.equal(h.calls.length,count);s=await h.client.refresh();assert.equal(s.uncertain,true);assert.equal(s.deletions[0].state,'confirm');assert.equal(s.deletion.confirmationHandle,null);const read=h.calls.length;s=await h.client.openDeletion(s.deletions[0].operationHandle);assert.ok(h.calls.slice(read).every(c=>c.method==='GET'));assert.notEqual(s.deletion.confirmationHandle,old);assert.equal(s.deletion.uncertain,true);s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.deletion.state,'deleted');const confirmations=h.calls.filter(c=>c.path.endsWith('/confirm'));assert.equal(confirmations.length,2);assert.equal(confirmations[0].headers['Idempotency-Key'],confirmations[1].headers['Idempotency-Key']);assert.deepEqual(confirmations[0].body,confirmations[1].body);assert.equal(h.cleanupCalls,1);});
test('operation errors never replace availability reasons through lost confirmation, failed GET and explicit exact recovery',async()=>{
  const unavailable='Motet reading is unavailable. Kept files can still be managed.';
  for(const [label,settings,reason,modelId]of [
    ['qualified',{},null,model],['off',{documentsEnabled:false},unavailable,model],['null-model',{},unavailable,null],
    ['unqualified',{unqualified:true},'Motet file reading requires the qualified model and host policy.',model],
    ['policy-refused',{capError:'policy_unavailable'},unavailable,model]
  ]){
    const h=harness({retained:true,...settings}),r=h.req(10);h.setRows([r]);h.answers.set(r.answerId,h.ans(r));
    let s=await h.client.connect({scopeId:'room',modelId});assert.equal(s.reason,reason,label);const available=s.available,hadAnswer=s.answers.length===1,start=h.changes.length;
    s=await h.client.prepareDeletion(id(2));const operation=s.deletion.id,old=s.deletion.confirmationHandle;let loseConfirm=true,failRead=false;
    h.beforeRoute=c=>{if(c.path.endsWith('/confirm')&&loseConfirm){loseConfirm=false;throw Error('Fictional pre-dispatch loss');}if(c.method==='GET'&&c.path.startsWith('/deletions/')&&failRead){failRead=false;throw Error('Fictional failed status read');}};
    s=await h.client.confirmDeletion(old);assert.ok(s.error?.message,label);assert.equal(s.reason,reason,label);assert.equal(s.uncertain,true);assert.deepEqual(s.answers,[]);assert.equal(h.cleanupCalls,0);
    const recovery=h.calls.length;s=await h.client.refresh();assert.equal(s.error,null);assert.equal(s.uncertain,true);assert.equal(s.deletions[0].id,operation);assert.equal(s.deletions[0].state,'confirm');assert.deepEqual(s.answers,[]);assert.ok(s.files.every(f=>f.previewHandle===null));
    failRead=true;s=await h.client.refresh();assert.ok(s.error?.message,label);assert.equal(s.complete,false);assert.equal(s.uncertain,true);assert.deepEqual(s.answers,[]);
    s=await h.client.refresh();assert.equal(s.error,null);assert.equal(s.complete,true);assert.equal(s.uncertain,true);assert.deepEqual(s.answers,[]);
    s=await h.client.closeDeletion();assert.equal(s.deletion,null);assert.equal(s.uncertain,true);assert.equal(h.cleanupCalls,0);
    s=await h.client.openDeletion(s.deletions[0].operationHandle);assert.equal(s.deletion.id,operation);assert.equal(s.deletion.fileId,id(2));assert.equal(s.deletion.uncertain,true);assert.notEqual(s.deletion.confirmationHandle,old);assert.ok(h.calls.slice(recovery).every(c=>c.method==='GET'));
    const count=h.calls.length;s=await h.client.confirmDeletion(s.deletion.confirmationHandle);
    assert.equal(s.error,null);assert.equal(s.reason,reason,label);assert.equal(s.available,available,label);assert.equal(s.uncertain,false);assert.equal(s.deletion.id,operation);assert.equal(s.deletion.fileId,id(2));assert.equal(s.deletion.state,'deleted');assert.equal(s.deletion.sourceUnavailable,true);assert.equal(s.management.files[0].available,false);
    if(hadAnswer){assert.equal(s.answers.length,1);assert.equal(s.answers[0].id,r.answerId);assert.equal(s.answers[0].state,'source_unavailable');assert.equal(s.answers[0].text,null);assert.deepEqual(s.answers[0].suppliedFileIds,[]);assert.deepEqual(s.answers[0].citations,[]);}
    const confirms=h.calls.filter(c=>c.path.endsWith('/confirm'));assert.equal(confirms.length,2);assert.equal(confirms[0].headers['Idempotency-Key'],confirms[1].headers['Idempotency-Key']);assert.deepEqual(confirms[0].body,confirms[1].body);assert.equal(h.cleanupCalls,1);
    assert.equal(h.calls.slice(count).filter(c=>c.method!=='GET').length,1);assert.equal(h.calls.filter(c=>c.method!=='GET').length,3);
    for(const emitted of h.changes.slice(start))assert.equal(emitted.reason,reason,label+' availability reason remains independent of operation errors');
  }
});
test('unavailable and initial refusal reasons survive operation errors and GET recovery without changing qualification',async()=>{
  for(const settings of [{capError:'attachments_disabled'},{capError:'unrecognized_refusal'}]){
    const h=harness(settings);let s=await h.connect();const reason=s.reason,begin=h.changes.length;assert.equal(s.available,false);
    const before=h.calls.length;s=await h.client.send('Refused question');assert.equal(s.error.code,'mutation_blocked');assert.equal(h.calls.length,before);assert.equal(s.reason,reason);
    h.beforeRoute=c=>{if(c.method==='GET')throw Error('Fictional failed GET');};s=await h.client.refresh();assert.ok(s.error);assert.equal(s.reason,reason);
    h.beforeRoute=null;const reads=h.calls.length;s=await h.client.refresh();assert.equal(s.error,null);assert.equal(s.reason,reason);assert.equal(s.available,false);assert.ok(h.calls.slice(reads).every(c=>c.method==='GET'));
    assert.ok(h.changes.slice(begin).every(v=>v.reason===reason));
  }
});
test('unknown provider holds survive deletion, refresh and visibility invalidation without another question',async()=>{const h=harness({retained:true});await h.connect();const gate=deferred(),entered=deferred();h.beforeRoute=async c=>{if(c.path.startsWith('/requests/')&&c.path.endsWith('/ask')){entered.resolve();await gate.promise;}};const first=h.client.send('A remains unresolved');await entered.promise;h.client.invalidate();let s=await h.connect();assert.equal(s.uncertain,true);s=await h.client.prepareDeletion(s.management.files[0].id);s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.deletion.state,'deleted');assert.equal(s.uncertain,true);const count=h.calls.length;await h.client.send('No duplicate may be created');assert.equal(h.calls.length,count);assert.equal(h.calls.filter(c=>c.path.endsWith('/question-intent')).length,1);h.beforeRoute=null;gate.resolve();await first;});
