test('both delayed-confirm arrival orders reuse the same exact command and perform cleanup once',async()=>{for(const order of ['old-first','repeat-first']){const jobs=[];const timers={setTimeout:(fn,ms)=>{const job={fn,ms,cleared:false};jobs.push(job);return job;},clearTimeout:job=>job.cleared=true};const h=harness({retained:true,documentsEnabled:false,timers});let s=await h.connect();s=await h.client.prepareDeletion(s.management.files[0].id);const gate=deferred(),entered=deferred(),arrived=deferred();let firstCall;h.beforeRoute=async c=>{if(c.path.endsWith('/confirm')&&!firstCall){firstCall=c;entered.resolve();await gate.promise;}};h.setHook((c,v)=>{if(c===firstCall)arrived.resolve();return v;});const first=h.client.confirmDeletion(s.deletion.confirmationHandle);await entered.promise;jobs.findLast(j=>!j.cleared&&j.ms===15000).fn();s=await first;assert.equal(s.uncertain,true);assert.equal(h.cleanupCalls,0);await h.client.closeDeletion();assert.equal(h.client.snapshot().deletion,null);s=await h.client.refresh();assert.equal(s.uncertain,true);s=await h.client.openDeletion(s.deletions[0].operationHandle);assert.ok(s.deletion.confirmationHandle);if(order==='old-first'){gate.resolve();await arrived.promise;}s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.error,null);assert.equal(s.deletion.state,'deleted');if(order==='repeat-first'){gate.resolve();await arrived.promise;}assert.equal(h.client.snapshot().deletions[0].state,'deleted');assert.equal(h.cleanupCalls,1);const confirmations=h.calls.filter(c=>c.path.endsWith('/confirm'));assert.equal(confirmations.length,2);assert.equal(confirmations[0].headers['Idempotency-Key'],confirmations[1].headers['Idempotency-Key']);assert.deepEqual(confirmations[0].body,confirmations[1].body);}});
test('reload may explicitly compete only for the same prepared selection and reads the immutable winner after key conflict',async()=>{for(const order of ['old-first','reload-first']){const jobs=[];const timers={setTimeout:(fn,ms)=>{const j={fn,ms,cleared:false};jobs.push(j);return j;},clearTimeout:j=>j.cleared=true};const old=harness({retained:true,documentsEnabled:false,timers});let s=await old.connect();s=await old.client.prepareDeletion(s.management.files[0].id);const gate=deferred(),entered=deferred(),arrived=deferred();let issued;old.beforeRoute=async c=>{if(c.path.endsWith('/confirm')&&!issued){issued=c;entered.resolve();await gate.promise;}};old.setHook((c,v)=>{if(c===issued)arrived.resolve();return v;});const pending=old.client.confirmDeletion(s.deletion.confirmationHandle);await entered.promise;jobs.findLast(j=>!j.cleared&&j.ms===15000).fn();await pending;old.client.dispose();const cold=harness({retained:true,documentsEnabled:false});cold.shareDeletionFrom(old);s=await cold.connect();s=await cold.client.openDeletion(s.deletions[0].operationHandle);assert.equal(s.deletion.fileId,old.deleteOps.values().next().value.fileId);if(order==='old-first'){gate.resolve();await arrived.promise;}s=await cold.client.confirmDeletion(s.deletion.confirmationHandle);if(order==='old-first'){assert.equal(s.error.code,'request_conflict');assert.equal(s.uncertain,true);s=await cold.client.refresh();}else{assert.equal(s.error,null);gate.resolve();await arrived.promise;}assert.equal(s.deletions[0].state,'deleted');assert.equal(old.cleanupCalls+cold.cleanupCalls,1);const replay=cold.calls.find(c=>c.path.endsWith('/confirm'));assert.notEqual(replay.headers['Idempotency-Key'],issued.headers['Idempotency-Key']);assert.deepEqual(replay.body,issued.body);assert.equal(cold.calls.filter(c=>c.path.endsWith('/deletion-intent')).length,0);}});
test('a held deletion retains its exact page locator and command across invalidate, navigation and model change',async()=>{const h=harness({retained:true,documentsEnabled:false,managementCount:51});let s=await h.connect();s=await h.client.managementPage(s.management.nextHandle);assert.equal(s.management.page,2);s=await h.client.prepareDeletion(s.management.files[0].id);const operation=s.deletion.id,oldHandle=s.deletion.confirmationHandle;let first=true;h.beforeRoute=c=>{if(c.path.endsWith('/confirm')&&first){first=false;throw Error('pre-dispatch loss');}};s=await h.client.confirmDeletion(oldHandle);const original=h.calls.find(c=>c.path.endsWith('/confirm'));assert.equal(s.uncertain,true);h.client.invalidate();assert.deepEqual(h.client.snapshot().deletions,[]);s=await h.connect();assert.equal(s.management.page,2);assert.equal(s.uncertain,true);assert.equal(s.deletions[0].id,operation);const count=h.calls.length;await h.client.confirmDeletion(oldHandle);assert.equal(h.calls.length,count);s=await h.client.managementPage(s.management.firstHandle);assert.equal(s.management.page,1);assert.equal(s.uncertain,true);const blocked=h.calls.length;await h.client.prepareDeletion(s.management.files[0].id);assert.equal(h.calls.length,blocked);s=await h.client.connect({scopeId:'room',modelId:'unsupported-model'});assert.equal(s.uncertain,true);assert.equal(s.management.page,1);s=await h.client.managementPage(s.management.nextHandle);s=await h.client.openDeletion(s.deletions.find(d=>d.id===operation).operationHandle);s=await h.client.confirmDeletion(s.deletion.confirmationHandle);assert.equal(s.error,null);assert.equal(s.deletion.state,'deleted');assert.equal(h.calls.filter(c=>c.path.endsWith('/confirm')).at(-1).headers['Idempotency-Key'],original.headers['Idempotency-Key']);assert.equal(h.cleanupCalls,1);});
