test('D7 rejected carried page cursor leaves an explicit first-page GET recovery while retaining issued holds',async()=>{const h=harness({retained:true,documentsEnabled:false,managementCount:51});let s=await h.connect();s=await h.client.managementPage(s.management.nextHandle);s=await h.client.prepareDeletion(s.management.files[0].id);const op=s.deletion.id;h.beforeRoute=c=>{if(c.path.endsWith('/confirm'))throw Error('not delivered');};await h.client.confirmDeletion(s.deletion.confirmationHandle);h.client.invalidate();h.setHook((c,v)=>c.path.includes('/management')&&new URL('http://fictional.invalid'+c.path).searchParams.has('cursor')?{error:{code:'invalid_cursor',message:'The cursor expired.'}}:v);s=await h.connect();assert.equal(s.error.code,'invalid_cursor');assert.equal(s.management.complete,false);assert.equal(s.management.available,false);assert.ok(s.management.firstHandle);assert.equal(s.uncertain,true);const before=h.calls.length;s=await h.client.managementPage(s.management.firstHandle);assert.equal(s.error,null);assert.equal(s.management.page,1);assert.equal(s.management.complete,true);assert.equal(s.uncertain,true);assert.ok(h.calls.slice(before).every(c=>c.method==='GET'));assert.ok(!new URL('http://fictional.invalid'+h.calls.at(-1).path).searchParams.has('cursor'));const blocked=h.calls.length;await h.client.prepareDeletion(s.management.files[0].id);assert.equal(h.calls.length,blocked);h.setHook(null);s=await h.client.managementPage(s.management.nextHandle);assert.equal(s.deletions.find(d=>d.id===op).uncertain,true);assert.equal(s.uncertain,true);assert.equal(h.calls.filter(c=>c.path.endsWith('/deletion-intent')).length,1);assert.equal(h.calls.filter(c=>c.path.endsWith('/confirm')).length,1);});
