test('closed deletion rows expose only their exact issued confirmation uncertainty, independently of provider and other operations',async()=>{const h=harness({retained:true,managementCount:2});h.setRows([h.req(10,'unknown')]);let s=await h.connect();s=await h.client.prepareDeletion(id(2));const a=s.deletion.id;await h.client.closeDeletion();s=await h.client.prepareDeletion(id(3));const b=s.deletion.id;assert.equal(s.deletions.find(d=>d.id===a).uncertain,false);assert.equal(s.deletions.find(d=>d.id===b).uncertain,false);h.beforeRoute=c=>{if(c.path.endsWith('/confirm'))throw Error('not delivered');};await h.client.confirmDeletion(s.deletion.confirmationHandle);s=await h.client.closeDeletion();assert.equal(s.deletion,null);assert.equal(s.uncertain,true);assert.equal(s.deletions.find(d=>d.id===a).uncertain,false);assert.equal(s.deletions.find(d=>d.id===b).uncertain,true);});

test('positive blank keep and file question retire only their exact admitted local selection before post-admission emissions',async()=>{for(const text of ['','An explicit file question']){const h=harness({selectedModel:'@automatic'});await h.connect();let s=await h.client.addFiles([selected()]);const chosen=s.uploads[0],source=s.draft.files[0].id;assert.equal(chosen.fileId,source);let ack;h.setHook((c,v)=>{if(c.path.endsWith('/send'))ack=h.changes.length;return v;});s=await h.client.send(text);assert.equal(s.error,null);assert.deepEqual(s.uploads,[]);assert.equal(s.draft,null);assert.ok(s.files.some(f=>f.id===source));assert.ok(h.changes.slice(ack).every(view=>!view.uploads.some(u=>u.id===chosen.id)));assert.equal(s.requests[0].draftId,id(4));assert.equal(s.requests[0].state,text?'answered':'retained_local');assert.equal(s.answers.length,text?1:0);if(!text){s=await h.client.send('A later question on the retained file');assert.equal(s.error,null);assert.deepEqual(s.uploads,[]);assert.equal(s.answers[0].model.id,model);}}});
