test('lost consumed execution acknowledgement retires selections only after exact request and retained source identity reconcile',async()=>{const h=harness();await h.connect();let s=await h.client.addFiles([selected()]);const local=s.uploads[0],source=local.fileId;h.setHook(c=>{if(c.path.endsWith('/send'))throw Error('lost consumed response');});s=await h.client.send('A positively admitted question with a lost acknowledgement');assert.equal(s.uncertain,true);assert.equal(s.uploads[0].id,local.id);h.setHook((c,v)=>c.path.startsWith('/files?')?{items:[h.file(999)],nextCursor:null}:v);const reads=h.calls.length;s=await h.client.refresh();assert.equal(s.requests[0].state,'answered');assert.equal(s.requests[0].draftId,id(4));assert.equal(s.error.code,'invalid_response');assert.equal(s.uploads[0].id,local.id,'same name and size on an older source must not retire this selection');assert.equal(s.files[0].name,local.name);assert.equal(s.files[0].bytes,local.bytes);assert.notEqual(s.files[0].id,source);const before=h.calls.length;s=await h.client.send('Cannot silently omit the unreconciled selection');assert.equal(s.error.code,'mutation_blocked');assert.equal(h.calls.length,before);h.setHook(null);s=await h.client.refresh();assert.deepEqual(s.uploads,[]);assert.ok(s.files.some(f=>f.id===source));assert.ok(h.calls.slice(reads).every(c=>c.method==='GET'));assert.equal(h.calls.filter(c=>c.path.endsWith('/send')).length,1);});
test('acknowledged unknown provider delivery can retire positively admitted frozen local selections without clearing provider uncertainty',async()=>{const h=harness();await h.connect();let s=await h.client.addFiles([selected()]);let ack;h.setHook((c,v)=>{if(c.path.endsWith('/send')){const row=h.rows.find(r=>r.requestId===v.requestId);row.state='unknown';row.answerId=null;row.officerDelivery={state:'unknown',requestId:row.requestId};ack=h.changes.length;return row;}return v;});s=await h.client.send('Admit locally while provider outcome remains unknown');assert.equal(s.error,null);assert.equal(s.uncertain,true);assert.deepEqual(s.uploads,[]);assert.equal(s.requests[0].state,'unknown');assert.ok(h.changes.slice(ack).every(view=>view.uploads.length===0));const count=h.calls.length;await h.client.send('Must not duplicate an unresolved call');assert.equal(h.calls.length,count);});
test('failed and unprocessed selections cannot be silently omitted from a ready draft or retained-only follow-up',async()=>{const h=harness();await h.connect();let laterReads=0;let s=await h.client.addFiles([selected(),{...selected('failed.pdf'),arrayBuffer:async()=>{throw Error('local failure');}},{...selected('unprocessed.pdf'),arrayBuffer:async()=>{laterReads++;return new ArrayBuffer(4);}}]);assert.deepEqual(s.uploads.map(u=>u.state),['ready','failed','failed']);assert.equal(s.draft.files.length,1);assert.equal(laterReads,0);const ready=s.uploads[0].id,bad=s.uploads.slice(1).map(u=>u.id),count=h.calls.length;s=await h.client.send('All owner selections must be accounted for');assert.equal(s.error.code,'selection_not_ready');assert.equal(s.lastSend.retained,false);assert.equal(h.calls.length,count);assert.deepEqual(s.uploads.map(u=>u.id),[ready,...bad]);for(const localId of bad)s=await h.client.removeUpload(localId);assert.deepEqual(s.uploads.map(u=>u.id),[ready]);s=await h.client.send('Now explicitly send the remaining ready file');assert.equal(s.error,null);assert.deepEqual(s.uploads,[]);assert.equal(h.calls.filter(c=>c.path.endsWith('/send')).length,1);const follow=harness({retained:true});await follow.connect();s=await follow.client.addFiles([{...selected(),arrayBuffer:async()=>{throw Error('not read');}}]);const followCount=follow.calls.length;s=await follow.client.send('Do not omit a failed newly selected file');assert.equal(s.error.code,'selection_not_ready');assert.equal(follow.calls.length,followCount);assert.equal(follow.calls.filter(c=>c.path.endsWith('/question-intent')).length,0);});
test('acknowledged explicit file removal retires only that local row and leaves the other selection sendable',async()=>{const h=harness();await h.connect();let s=await h.client.addFiles([selected(),selected('other.pdf')]);const first=s.uploads[0],second=s.uploads[1];s=await h.client.remove(first.fileId);assert.equal(s.error,null);assert.deepEqual(s.uploads.map(u=>u.id),[second.id]);assert.deepEqual(s.draft.files.map(f=>f.id),[second.fileId]);s=await h.client.send('Send the explicitly remaining file');assert.equal(s.error,null);assert.deepEqual(s.uploads,[]);assert.ok(s.files.some(f=>f.id===second.fileId));assert.ok(!s.files.some(f=>f.id===first.fileId));});

test('an identical source ID attributed to an older retained request cannot substitute for the frozen current draft admission',async()=>{const h=harness({retained:true});await h.connect();let s=await h.client.addFiles([selected()]);const local=s.uploads[0];h.beforeRoute=c=>{if(c.path.endsWith('/send'))throw Error('current intent was not consumed');};await h.client.send('The current draft must have its own admission proof');h.beforeRoute=null;const older=h.req(500,'answered','An older retained question');older.draftId=id(99);h.rows.push(older);h.answers.set(older.answerId,h.ans(older));const source={...h.file(),id:local.fileId,officerDelivery:{state:'confirmed',requestId:older.requestId}};h.setHook((c,v)=>c.path.startsWith('/files?')?{items:[source],nextCursor:null}:v);s=await h.client.refresh();assert.ok(s.files.some(f=>f.id===local.fileId));assert.ok(s.requests.some(r=>r.requestId===older.requestId&&r.state==='answered'));assert.ok(s.requests.some(r=>r.draftId===id(4)&&r.state==='prepared'));assert.deepEqual(s.uploads.map(u=>u.id),[local.id]);assert.equal(s.uncertain,true);});

test('presentation origin stays on blank admission when a later question supplies the same file',async()=>{const h=harness();await h.connect();await h.client.addFiles([selected()]);let s=await h.client.send('');const origin=s.requests[0].requestId,source=s.files[0].id;assert.equal(s.files[0].admissionRequestId,origin);s=await h.client.send('A later question on the retained original');assert.equal(s.error,null);assert.equal(s.files[0].admissionRequestId,origin);assert.notEqual(s.files[0].officerDelivery.requestId,origin);assert.deepEqual(s.answers[0].suppliedFileIds,[source]);});
test('retained admission origins require an explicit checked nullable field and a real consumed draft request',async()=>{for(const mode of ['missing','wrong-type','foreign','follow-up','prepared','abandoned']){const h=harness({retained:true}),file=h.file(),r=h.req(10,mode==='prepared'?'prepared':mode==='abandoned'?'failed':'retained_local');r.draftId=mode==='follow-up'?null:id(4);if(mode==='abandoned'){r.abandoned=true;r.officerDelivery={state:'not_sent',requestId:null};}file.admissionRequestId=mode==='foreign'?id(99):r.requestId;if(mode==='missing')delete file.admissionRequestId;if(mode==='wrong-type')file.admissionRequestId=1;h.setFiles([file]);h.setRows([r]);const s=await h.connect();assert.ok(s.error,mode+' must refuse');assert.equal(s.error.code,'invalid_response',mode);assert.equal(s.complete,false);assert.equal(s.routing,'documents');}const legacy=harness({retained:true});const s=await legacy.connect();assert.equal(s.error,null);assert.equal(s.files[0].admissionRequestId,null);});
test('answer supplied originals remain ordered and complete independently of citation subset and later current files',async()=>{const h=harness({retained:true}),r=h.req(10),a=h.file(2),b={...h.file(3),mediaType:'image/png'};h.setFiles([a,b]);r.suppliedFileIds=[b.id,a.id];h.setRows([r]);h.answers.set(r.answerId,{...h.ans(r),citations:[{id:r.answerId+':0',kind:'upload',fileId:a.id,label:'PDF page 2',location:{page:2},available:true,sourceCapability:'fictional-source-secret'}]});let s=await h.connect();assert.equal(s.error,null);assert.deepEqual(s.answers[0].suppliedFileIds,[b.id,a.id]);assert.deepEqual(s.answers[0].citations.map(c=>c.fileId),[a.id]);h.setFiles([a,b,h.file(4)]);s=await h.client.refresh();assert.equal(s.error,null);assert.deepEqual(s.answers[0].suppliedFileIds,[b.id,a.id]);});
test('available supplied-roster and display contract rejects missing, duplicate, foreign, absent and inconsistent facts',async()=>{for(const mode of ['missing','duplicate','foreign-id','empty','missing-file','unavailable-file','citation-outside','raw-marker']){const h=harness({retained:true}),r=h.req(10);h.setRows([r]);const a=h.ans(r);if(mode==='missing')delete a.suppliedFileIds;if(mode==='duplicate')a.suppliedFileIds=[id(2),id(2)];if(mode==='foreign-id')a.suppliedFileIds=['not-a-source'];if(mode==='empty')a.suppliedFileIds=[];if(mode==='missing-file')a.suppliedFileIds=[id(99)];if(mode==='unavailable-file')h.setFiles([{...h.file(),available:false}]);if(mode==='citation-outside')a.citations=[{id:r.answerId+':0',kind:'upload',fileId:id(99),label:'Whole image',location:{image:true},available:true,sourceCapability:'fictional-source-secret'}];if(mode==='raw-marker')a.text='Fictional.\nIMAGE_SOURCE: image-1';h.answers.set(r.answerId,a);const s=await h.connect();assert.ok(s.error,mode+' must refuse');assert.equal(s.error.code,'invalid_response',mode);assert.deepEqual(s.answers,[]);assert.equal(s.complete,false);assert.equal(s.routing,'documents');}});
test('citation-only available display accepts mixed PDF/image evidence while unavailable remains null and empty',async()=>{for(const mixed of [false,true]){const h=harness({retained:true}),r=h.req(10),png={...h.file(),mediaType:'image/png'},pdf=h.file(3);h.setFiles(mixed?[png,pdf]:[png]);r.suppliedFileIds=mixed?[png.id,pdf.id]:[png.id];h.setRows([r]);const citations=[{id:r.answerId+':0',kind:'upload',fileId:png.id,label:'Whole image',location:{image:true},available:true,sourceCapability:'fictional-source-secret'}];if(mixed)citations.push({id:r.answerId+':1',kind:'upload',fileId:pdf.id,label:'PDF page 2',location:{page:2},available:true,sourceCapability:'fictional-source-secret'});h.answers.set(r.answerId,{...h.ans(r),text:'',citations});let s=await h.connect();assert.equal(s.error,null);assert.equal(s.answers[0].text,'');assert.equal(s.answers[0].citations.length,mixed?2:1);h.answers.set(r.answerId,{...h.ans(r),state:'source_unavailable',sourceValidation:'invalid',text:null,suppliedFileIds:[],citations:[]});s=await h.client.refresh();assert.equal(s.error,null);assert.equal(s.answers[0].text,null);assert.deepEqual(s.answers[0].suppliedFileIds,[]);}for(const mode of ['available-without-image','unavailable-with-roster','unavailable-missing']){const h=harness({retained:true}),r=h.req(10);h.setRows([r]);const a=mode==='available-without-image'?{...h.ans(r),text:''}:{...h.ans(r),state:'source_unavailable',sourceValidation:'invalid',text:null,citations:[]};if(mode==='unavailable-missing')delete a.suppliedFileIds;h.answers.set(r.answerId,a);const s=await h.connect();assert.equal(s.error.code,'invalid_response');assert.deepEqual(s.answers,[]);}});
(async()=>{for(const {name,fn} of tests){try{await fn();process.stdout.write('ok '+name+'\n');}catch(e){console.error('FAIL '+name);throw e;}}process.stdout.write(tests.length+' Motet document client checks passed\n');})().catch(e=>{console.error(e);process.exitCode=1;});
